html:
{%- set emp = frappe.db.get_value("Employee", doc.employee,
    ["employee_name","designation","department","branch","date_of_joining"], as_dict=True) or {} %}
{%- set cyc = frappe.db.get_value("Performance Cycle", doc.cycle,
    ["title","cycle_type","start_date","end_date"], as_dict=True) or {} %}
<!DOCTYPE html><html><head><meta charset="UTF-8"/>
<style>
* { margin:0; padding:0; box-sizing:border-box; }
body { font-family: Calibri, Arial, sans-serif; font-size: 11pt; color: #1E293B; }
.page-header { background: linear-gradient(135deg, #1E2D5A 0%, #5B2D8E 100%);
  padding: 24px 32px; color: white; display: flex;
  justify-content: space-between; align-items: flex-start; }
.brand { font-size: 18pt; font-weight: 900; letter-spacing: -1px; }
.brand-sub { font-size: 8pt; color: rgba(255,255,255,.65); margin-top: 2px; }
.doc-meta { text-align: right; }
.doc-meta h1 { font-size: 14pt; font-weight: 800; }
.doc-meta p  { font-size: 8pt; color: rgba(255,255,255,.7); margin-top: 3px; }
.emp-band { background:#F1F5F9; border-left:5px solid #5B2D8E;
  padding:12px 32px; display:flex; gap:28px; flex-wrap:wrap; }
.ef .el { font-size:8pt; font-weight:700; color:#64748B;
  text-transform:uppercase; letter-spacing:.4px; }
.ef .ev { font-size:10pt; font-weight:600; margin-top:2px; }
.sec { padding:14px 32px; border-bottom:1px solid #E5E7EB; }
.sec-h { font-size:10pt; font-weight:800; color:#5B2D8E; text-transform:uppercase;
  letter-spacing:.5px; border-bottom:2px solid #5B2D8E; padding-bottom:5px;
  margin-bottom:10px; }
table { width:100%; border-collapse:collapse; margin:6px 0; }
th { background:#1E2D5A; color:white; padding:7px 10px;
  font-size:8.5pt; font-weight:700; text-align:left; }
td { padding:7px 10px; font-size:9.5pt; border-bottom:1px solid #F1F5F9; }
tr:nth-child(even) td { background:#F8FAFC; }
.nb { background:#F8FAFC; border:1px solid #E2E8F0; border-radius:5px;
  padding:10px 14px; min-height:50px; font-size:9.5pt; line-height:1.6;
  white-space:pre-wrap; }
.pill { display:inline-block; padding:2px 10px; border-radius:99px;
  font-weight:700; font-size:8.5pt; }
.green { background:#D1FAE5; color:#065F46; }
.blue  { background:#DBEAFE; color:#1D4ED8; }
.amber { background:#FEF3C7; color:#92400E; }
.red   { background:#FEE2E2; color:#991B1B; }
.purple{ background:#EDE9FE; color:#5B21B6; }
.score-hero { text-align:center; background:#F0FDF4;
  border:2px solid #6EE7B7; border-radius:10px; padding:14px; margin:8px 0; }
.score-num { font-size:30pt; font-weight:900; color:#059669; }
.score-lbl { font-size:9pt; color:#6B7280; }
.sig-row { display:flex; gap:28px; margin-top:6px; }
.sig-box { flex:1; }
.sig-line { border-bottom:1.5px solid #1E2D5A; margin-top:28px; margin-bottom:5px; }
.sig-name { font-size:8.5pt; color:#6B7280; }
.page-footer { background:#F8FAFC; border-top:1px solid #E2E8F0;
  padding:8px 32px; display:flex; justify-content:space-between;
  font-size:7.5pt; color:#94A3B8; }

.perf-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin:8px 0; }
.pc { text-align:center; border:1px solid #E2E8F0; border-radius:8px; padding:12px 8px; }
.pc-num { font-size:22pt; font-weight:900; }
.pc-lbl { font-size:8pt; color:#6B7280; font-weight:600; margin-top:2px; }
.band-hero { text-align:center; border-radius:10px; padding:18px;
  margin:10px 0; border:2px solid; }
.rec-list { list-style:none; }
.rec-list li { padding:5px 0; border-bottom:1px solid #F1F5F9;
  font-size:9.5pt; display:flex; align-items:center; gap:8px; }
</style></head><body>

<div class="page-header">
  <div><div class="brand">Ecclesia</div><div class="brand-sub">360° Performance Management</div></div>
  <div class="doc-meta"><h1>Performance Report Card</h1>
    <p>{{ cyc.title or doc.cycle }}</p>
    <p>{{ doc.name }} | {{ frappe.format_date(frappe.utils.nowdate()) }}</p></div>
</div>

<div class="emp-band">
  <div class="ef"><div class="el">Employee</div><div class="ev">{{ emp.employee_name or doc.employee }}</div></div>
  <div class="ef"><div class="el">Designation</div><div class="ev">{{ emp.designation or "—" }}</div></div>
  <div class="ef"><div class="el">Department</div><div class="ev">{{ emp.department or "—" }}</div></div>
  <div class="ef"><div class="el">Branch</div><div class="ev">{{ emp.branch or "—" }}</div></div>
  <div class="ef"><div class="el">Record Status</div>
    <div class="ev"><span class="pill {% if doc.status=='Released' %}green{% elif doc.status=='Final' %}blue{% elif doc.status=='Calibrated' %}purple{% else %}amber{% endif %}">{{ doc.status }}</span></div></div>
</div>

{% set band = doc.performance_band or "Meets Expectations" %}
{% set band_colors = {
  "Outstanding": ("#D1FAE5","#065F46","#059669"),
  "Exceeds Expectations": ("#DBEAFE","#1D4ED8","#2563EB"),
  "Meets Expectations": ("#CCFBF1","#0F766E","#0D9488"),
  "Needs Improvement": ("#FEF3C7","#92400E","#D97706"),
  "Unsatisfactory": ("#FEE2E2","#991B1B","#DC2626")
} %}
{% set bc = band_colors.get(band, ("#F1F5F9","#374151","#64748B")) %}

<div class="sec">
  <div class="sec-h">🏆 Performance Band</div>
  <div class="band-hero" style="background:{{ bc[0] }};border-color:{{ bc[2] }};">
    <div style="font-size:26pt;font-weight:900;color:{{ bc[1] }};">
      {{ doc.final_rating or doc.calibrated_rating or doc.composite_score or "—" }}%
    </div>
    <div style="font-size:13pt;font-weight:700;color:{{ bc[1] }};margin-top:4px;">{{ band }}</div>
    {% if doc.performance_trend %}
    <div style="font-size:9pt;color:{{ bc[1] }};margin-top:6px;">{{ doc.performance_trend }}</div>
    {% endif %}
  </div>
</div>

<div class="sec">
  <div class="sec-h">📊 Component Scores</div>
  <div class="perf-grid">
    {% for label, field, color in [
      ("Goal / KPI", "kpi_score", "#F59E0B"),
      ("Self Score", "self_score", "#7C3AED"),
      ("Peer Average", "peer_score", "#0D9488"),
      ("Manager Score", "manager_score", "#2563EB"),
      ("Skip-Level", "skip_level_score", "#DB2777"),
      ("Composite", "composite_score", "#059669")] %}
    <div class="pc" style="border-color:{{ color }}20;">
      <div class="pc-num" style="color:{{ color }};">{{ doc.get(field) or "—" }}</div>
      <div class="pc-lbl">{{ label }}</div>
    </div>
    {% endfor %}
  </div>
</div>

{% if doc.promotion_recommended or doc.increment_recommended or doc.bonus_recommended %}
<div class="sec">
  <div class="sec-h">🎯 HR Recommendations</div>
  <ul class="rec-list">
    {% if doc.promotion_recommended %}
    <li><span class="pill green">✓</span> <b>Promotion Recommended</b></li>
    {% endif %}
    {% if doc.increment_recommended %}
    <li><span class="pill green">✓</span> <b>Salary Increment:</b> {{ doc.increment_percentage or "" }}% recommended</li>
    {% endif %}
    {% if doc.bonus_recommended %}
    <li><span class="pill blue">✓</span> <b>Bonus:</b> ₦{{ "{:,.0f}".format(doc.bonus_amount) if doc.bonus_amount else "TBD" }}</li>
    {% endif %}
  </ul>
</div>
{% endif %}

{% if doc.calibration_notes %}
<div class="sec"><div class="sec-h">⚖️ Calibration Notes</div>
  <div class="nb">{{ doc.calibration_notes }}</div></div>
{% endif %}

{% if doc.hr_notes %}
<div class="sec"><div class="sec-h">📝 HR Notes</div>
  <div class="nb">{{ doc.hr_notes }}</div></div>
{% endif %}

<div class="sec"><div class="sec-h">✍️ Confirmation</div>
  <div class="sig-row">
    <div class="sig-box"><div class="sig-line"></div>
      <div class="sig-name"><b>{{ emp.employee_name or doc.employee }}</b><br>Employee</div></div>
    <div class="sig-box"><div class="sig-line"></div>
      <div class="sig-name"><b>Line Manager</b></div></div>
    <div class="sig-box"><div class="sig-line"></div>
      <div class="sig-name"><b>HR Manager</b></div></div>
  </div>
</div>

<div class="page-footer">
  <span>Ecclesia HR · Value Impacts Consulting</span>
  <span>{{ doc.name }} | Printed: {{ frappe.format_date(frappe.utils.nowdate()) }}</span>
  <span>CONFIDENTIAL</span>
</div>
</body></html>
